from datetime import date
from calendar import monthrange


def nth_weekday(year, month, weekday, n) -> str:
    if not 0 <= weekday <= 6:
        raise ValueError("weekday must be between 0 and 6")
    if n != -1 and not 1 <= n <= 5:
        raise ValueError("n must be between 1 and 5, or -1")

    first_day = date(year, month, 1)
    days_in_month = monthrange(year, month)[1]

    if n == -1:
        candidate = date(year, month, days_in_month)
        candidate = candidate.replace(
            day=days_in_month - ((candidate.weekday() - weekday) % 7)
        )
    else:
        day = 1 + ((weekday - first_day.weekday()) % 7) + 7 * (n - 1)
        if day > days_in_month:
            raise ValueError("the requested weekday occurrence does not exist")
        candidate = date(year, month, day)

    return candidate.isoformat()
